import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaFilter, FaPlus } from 'react-icons/fa';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import AdvertCard from '../../components/AdvertCard/AdvertCard';
import FilterSection from '../../components/FilterSection/FilterSection';
import advertService from '../../services/advertService';
import styles from './HomePage.module.css';

const HomePage = () => {
    const navigate = useNavigate();
    const { user, isAuthenticated } = useAuth();
    const [activeTab, setActiveTab] = useState('all');
    const [showFilters, setShowFilters] = useState(false);
    const [adverts, setAdverts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [filters, setFilters] = useState({});

    const loadAdverts = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            let response;
            switch (activeTab) {
                case 'my':
                    if (!isAuthenticated) { setAdverts([]); setLoading(false); return; }
                    response = await advertService.getMyAdverts();
                    break;
                case 'participating':
                    if (!isAuthenticated) { setAdverts([]); setLoading(false); return; }
                    response = await advertService.getParticipatingAdverts();
                    break;
                default:
                    response = await advertService.getAllAdverts(filters);
            }
            setAdverts(response.adverts || []);
        } catch (err) {
            setError(err.message || 'Ошибка загрузки объявлений');
        } finally {
            setLoading(false);
        }
    }, [activeTab, filters, isAuthenticated]);

    useEffect(() => { loadAdverts(); }, [loadAdverts]);

    const handleSubscribe = async (advertId, isParticipating) => {
        if (!isAuthenticated) { navigate('/login'); return; }
        try {
            if (isParticipating) await advertService.unsubscribeFromAdvert(advertId);
            else await advertService.subscribeToAdvert(advertId);
            await loadAdverts();
        } catch (err) { alert(err.message); }
    };

    const handleDelete = async (advertId) => {
        if (window.confirm('Вы уверены, что хотите удалить это объявление?')) {
            try { await advertService.deleteAdvert(advertId); await loadAdverts(); }
            catch (err) { alert(err.message); }
        }
    };

    const handleEdit = (advertId) => navigate(`/add-advert?edit=${advertId}`);
    const handleApplyFilters = (newFilters) => { setFilters(newFilters); setShowFilters(false); };

    const tabs = [
        { id: 'all', label: 'Все объявления' },
        { id: 'my', label: 'Мои объявления' },
        { id: 'participating', label: 'Участвую' }
    ];

    return (
        <div className={styles.homePage}>
            <div className={styles.hero}>
                <div className={styles.heroContent}>
                    <h1 className={styles.heroTitle}>Найди свою команду для волейбола</h1>
                    <p className={styles.heroSubtitle}>Присоединяйся к играм, создавай объявления и находи единомышленников</p>
                    {isAuthenticated ? (
                        <Button size="large" icon={FaPlus} onClick={() => navigate('/add-advert')}>Создать объявление</Button>
                    ) : (
                        <Button size="large" onClick={() => navigate('/login')}>Войти в аккаунт</Button>
                    )}
                </div>
            </div>

            <div className={styles.tabsSection}>
                <div className={styles.container}>
                    <div className={styles.tabsHeader}>
                        <div className={styles.tabs}>
                            {tabs.map(tab => (
                                <button key={tab.id} className={`${styles.tab} ${activeTab === tab.id ? styles.activeTab : ''}`} onClick={() => setActiveTab(tab.id)}>
                                    {tab.label}
                                </button>
                            ))}
                        </div>
                        <Button variant="outline" size="small" icon={FaFilter} onClick={() => setShowFilters(!showFilters)}>Фильтры</Button>
                    </div>

                    {showFilters && <FilterSection onApplyFilters={handleApplyFilters} />}

                    {loading ? (
                        <div className={styles.loadingState}><div className={styles.spinner} /><p>Загрузка объявлений...</p></div>
                    ) : error ? (
                        <div className={styles.errorState}><p>{error}</p><Button onClick={loadAdverts}>Попробовать снова</Button></div>
                    ) : adverts.length === 0 ? (
                        <div className={styles.emptyState}>
                            <p>Нет доступных объявлений</p>
                            {isAuthenticated && activeTab === 'all' && <Button onClick={() => navigate('/add-advert')}>Создать первое объявление</Button>}
                        </div>
                    ) : (
                        <div className={styles.advertsGrid}>
                            {adverts.map((advert) => {
                                const isCreator = user && advert.userId === user.id;
                                const isParticipating = user && advert.participatingUserIds?.split(',').includes(user.id.toString());
                                return (
                                    <AdvertCard key={advert.id} advert={advert} isCreator={isCreator} isParticipating={isParticipating}
                                                onSubscribe={() => handleSubscribe(advert.id, isParticipating)} onEdit={() => handleEdit(advert.id)}
                                                onDelete={() => handleDelete(advert.id)} onClick={() => navigate(`/advert/${advert.id}`)} />
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default HomePage;
